def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    # Build a matrix of fractions to avoid floating point issues
    # Use integer Gaussian elimination
    from fractions import Fraction
    m = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find pivot
        pivot = -1
        for r in range(i, n):
            if m[r][i] != 0:
                pivot = r
                break
        if pivot == -1:
            return 0
        if pivot != i:
            m[i], m[pivot] = m[pivot], m[i]
            det = -det
        det *= m[i][i]
        # Eliminate below
        for r in range(i+1, n):
            if m[r][i] != 0:
                factor = m[r][i] / m[i][i]
                for c in range(i, n):
                    m[r][c] -= factor * m[i][c]
    return int(det)

