    m = [list(row) for row in matrix]
    det = 1
    for i in range(n):
        pivot = -1
        for r in range(i, n):
            if m[r][i] != 0:
                pivot = r
                break
        if pivot == -1:
            return 0
        if pivot != i:
            m[i], m[pivot] = m[pivot], m[i]
            det = -det
        det *= m[i][i]
        for r in range(i+1, n):
            if m[r][i] != 0:
                # Use exact integer elimination with lcm of denominators
