                pass
        # Use Bareiss instead
    # Actually let me just use Bareiss from start
    return _bareiss(matrix)

def _bareiss(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    M = [list(row) for row in matrix]
    sign = 1
    denom = 1
    for i in range(n):
        if M[i][i] == 0:
            for r in range(i+1, n):
                if M[r][i] != 0:
                    M[i], M[r] = M[r], M[i]
                    sign = -sign
                    break
            else:
                return 0
        for r in range(i+1, n):
            for c in range(i+1, n):
                M[r][c] = (M[i][i]*M[r][c] - M[r][i]*M[i][c]) // denom
        for r in range(i+1, n):
            M[r][i] = 0
        denom = M[i][i] if M[i][i] != 0 else 1
    return sign * M[n-1][n-1]

